/* gml/gml_rt.h - GML runtime internals: instances, objects/events, the frame loop, helpers for builtin functions.
 * (gml.h is the small API the generated C uses.) */
#ifndef GM_GML_RT_H
#define GM_GML_RT_H
#include "gml/gml.h"

/* ---------------- game tables generated by the converter ---------------- */
typedef struct gm_objevent { int16_t type, sub; gm_fn fn; } gm_objevent;
typedef struct gm_objdef {
    const char *name;
    int sprite, parent, depth, mask;
    uint8_t visible, solid, persistent;
    int nevents;
    const gm_objevent *events;
} gm_objdef;
extern const gm_objdef gm_objs[];
extern const int gm_nobjs;

typedef struct gm_roominst { int x, y, obj, id; gm_fn code; } gm_roominst;
typedef struct gm_roomview { int enabled, x, y, w, h, px, py, pw, ph, hborder, vborder, hspeed, vspeed, object; } gm_roomview;
typedef struct gm_roomdef {
    const char *name;
    int w, h, speed;
    uint8_t persistent;
    gm_fn code;                       /* room creation code */
    int ninst;
    const gm_roominst *inst;
    gm_roomview views[8];
} gm_roomdef;
extern const gm_roomdef gm_rooms[];
extern const int gm_nrooms;
extern char gm_save_dir[256];

typedef struct gm_spritedef { const char *name; int w, h, ox, oy, left, right, bottom, top, nframes; const unsigned char *mask; } gm_spritedef;   /* mask: 1bpp precise collision mask (rows padded to bytes), NULL = bounding box */
extern const gm_spritedef gm_sprites[];
extern const int gm_nsprites;
typedef struct gm_pathdef { int smooth, closed, prec, n; const float *pts; } gm_pathdef;   /* pts: x,y,speed% per point */
extern const gm_pathdef gm_paths[];
extern const int gm_npaths;
void gm_path_start(gm_inst *i, int path, gm_real_t speed, int endaction, int absolute);
void gm_path_stop(gm_inst *i);
int  gm_inst_bbox(const gm_inst *i, gm_real_t *l, gm_real_t *t, gm_real_t *r, gm_real_t *b);   /* 0: no mask */
gm_inst *gm_collide_rect(gm_inst *self, gm_real_t l, gm_real_t t, gm_real_t r, gm_real_t b, int who, int notme);
gm_inst *gm_place(gm_inst *self, gm_real_t x, gm_real_t y, int who);       /* first instance `self` would overlap at (x,y) */
int  gm_collision_events(void);

/* event types as stored in OBJT */
enum { EV_CREATE = 0, EV_DESTROY = 1, EV_ALARM = 2, EV_STEP = 3, EV_COLLISION = 4, EV_KEYBOARD = 5, EV_MOUSE = 6, EV_OTHER = 7,
       EV_DRAW = 8, EV_KEYPRESS = 9, EV_KEYRELEASE = 10 };
enum { EVO_OUTSIDE = 0, EVO_BOUNDARY = 1, EVO_GAME_START = 2, EVO_GAME_END = 3, EVO_ROOM_START = 4, EVO_ROOM_END = 5, EVO_ANIM_END = 7,
       EVO_USER0 = 10 };

/* ---------------- variables ---------------- */
typedef struct gm_vtab { uint16_t *key; gm_val *val; int cap, n; } gm_vtab;     /* open addressing, key = vid + 1 */

struct gm_arr { int n; gm_val *v; gm_arr **rows; int nrows; };

#define GM_MAX_ALARMS 12
struct gm_inst {
    int id, obj;                      /* instance id (>= 100000), object index */
    uint8_t dead, visible, solid, persistent, created, anim_end;
    int sprite, mask, depth;
    gm_real_t x, y, xstart, ystart, xprev, yprev, hspeed, vspeed, direction, friction, gravity, gravity_dir;
    gm_real_t speed_set, sp_h, sp_v;   /* the speed last assigned and the hspeed/vspeed it produced: speed reads back exactly (and keeps its sign) until the components are touched */
    gm_real_t image_index, image_speed, image_xscale, image_yscale, image_angle, image_alpha;
    int image_blend;
    int alarm[GM_MAX_ALARMS];
    uint8_t path_on, path_end, path_abs; int path_idx; gm_real_t path_pos, path_spd, path_ox, path_oy;
    int ev_obj;                       /* object whose event code is currently running (for event_inherited) */
    gm_vtab vars;
};

/* ---------------- values / strings ---------------- */
gm_str *gm_str_new(const char *s, int len);              /* scratch (frame) string */
gm_val  gm_str_make(const char *s, int len);
gm_val  gm_str_cstr(const char *s);
gm_val  gm_promote(gm_val v);                            /* value about to be stored: scratch strings move to the heap */
void    gm_release(gm_val v);
void    gm_frame_end(void);                              /* resets the scratch arena, frees deferred strings */
gm_real_t gm_to_real(gm_val v);                          /* strings parse like real(), undefined = 0 */
int     gm_to_int(gm_val v);
const char *gm_cstr(gm_val v, char *tmp, int tmpsz);     /* string content (numbers formatted into tmp) */
gm_val  gm_format_real(gm_real_t r);
void    gm_arr_free(gm_arr *a);
gm_arr *gm_arr_copy(const gm_arr *a);
gm_val  gm_arr_get(const gm_arr *a, int idx);
void    gm_arr_set(gm_arr *a, int idx, gm_val v);

/* ---------------- instances / objects ---------------- */
void      gm_init(void);                                 /* builtin tables, global instance, global defaults */
gm_inst  *gm_instance_create(gm_real_t x, gm_real_t y, int obj);
void      gm_instance_destroy(gm_inst *i);               /* runs Destroy, marks dead; freed at frame end */
gm_inst  *gm_instance_by_id(int id);
int       gm_obj_isa(int obj, int target);               /* obj == target or a descendant */
int       gm_instance_count(int obj);                    /* live instances of obj (and children); obj < 0 = all */
gm_inst  *gm_instance_nth(int obj, int n);
void      gm_set_polar(gm_inst *i, gm_real_t speed, gm_real_t dir);   /* speed + direction -> hspeed/vspeed */
int       gm_find_object(const char *name);
void      gm_run_event(gm_inst *i, int type, int sub);   /* own event or inherited */
void      gm_run_event_for(gm_inst *i, int obj, int type, int sub, gm_inst *other);   /* handler defined in object `obj`, run for instance i */
gm_fn     gm_find_event_fn(int obj, int type, int sub, int *found_obj);
void      gm_event_inherited(gm_inst *i);
void      gm_vtab_set(gm_vtab *t, int vid, gm_val v);
int       gm_vtab_find(const gm_vtab *t, int vid, gm_val *out);
int       gm_vid(const char *name);                      /* -1 if the game has no such variable */

/* ---------------- frame loop ---------------- */
extern int gm_room_cur, gm_room_next;                    /* current room index, requested room (-1 none) */
extern gm_real_t gm_room_speed;
typedef struct gm_hooks {                                /* platform / game services */
    void (*room_start)(int room);                        /* instantiate the room (instances, tiles, backgrounds) */
    void (*room_end)(int room);
    void (*draw_begin)(void);
    void (*draw_end)(void);
    unsigned (*key_state)(int vk);                       /* bit0 down, bit1 pressed, bit2 released */
    void (*log)(const char *msg);
    void (*draw_layers)(int key);                        /* draw room tiles/backgrounds whose key (-depth) is <= key, in order, once */
    void (*draw_self)(gm_inst *i);                       /* default drawing of an instance without a Draw event */
    void *(*fs_read)(const char *name, int *len);        /* malloc'd file content or NULL (save dir relative) */
    int  (*fs_write)(const char *name, const void *data, int len);   /* 0 ok */
} gm_hooks;
extern gm_hooks gm_hk;
void gm_step(void);                                      /* one game frame: events, movement, destroy, room change */
int  gm_camera(int *x, int *y);                          /* view 0 top-left in room coordinates (0 = no visible view) */
void gm_draw(void);                                      /* draw events in depth order */
void gm_goto_room(int room);
extern uint64_t gm_frame;
unsigned gm_key_state(int vk);           /* key bits (1 held, 2 pressed, 4 released), 0 for a key cleared this step */
void gm_key_clear(int vk);

/* ---------------- helpers for builtins ---------------- */
#define GMB(name) gm_val gmb_##name(gm_inst *self, gm_inst *other, int argc, const gm_val *argv)
#define A_REAL(n) (gm_to_real(GM_ARG(n)))
#define A_INT(n) (gm_to_int(GM_ARG(n)))
void gm_logf(const char *fmt, ...) __attribute__((format(printf, 1, 2)));
void gm_lib_init(void);

#endif
